extern uint64_t fle_sys_clock_ticks(void);
extern a1_t a1_tab[];
extern unsigned a1_n;
int __real_getrusage(int who, struct rusage *ru);
void __real_fle_desk_wrote(uint32_t lid, int64_t x0, int64_t y0, int64_t x1, int64_t y1);
static long long wrote_us, wrote_n;   /* CPU time of the calls of fle_desk_wrote since the last dump */
void __wrap_fle_desk_wrote(uint32_t lid, int64_t x0, int64_t y0, int64_t x1, int64_t y1)
{
    struct timespec a, b;

    clock_gettime(CLOCK_THREAD_CPUTIME_ID, &a);
    __real_fle_desk_wrote(lid, x0, y0, x1, y1);
    clock_gettime(CLOCK_THREAD_CPUTIME_ID, &b);
    wrote_us += (b.tv_sec - a.tv_sec) * 1000000LL + (b.tv_nsec - a.tv_nsec) / 1000;
    wrote_n++;
}

static int peek(uint64_t addr, void *buf, size_t n)
{
    struct iovec l, r;
    if (addr < 0x1000) return 0;
    l.iov_base = buf; l.iov_len = n; r.iov_base = (void *)(uintptr_t)addr; r.iov_len = n;
    return process_vm_readv(getpid(), &l, 1, &r, 1, 0) == (ssize_t)n;
}
static uint32_t pk32(uint64_t a) { uint32_t v = 0; peek(a, &v, 4); return v; }
static uint64_t pk64(uint64_t a) { uint64_t v = 0; peek(a, &v, 8); return v; }

static void rd_w(uint64_t a, char *out, size_t cap)
{
    size_t i = 0;
    if (a < 0x10000) { snprintf(out, cap, "#atom%llu", (unsigned long long)a); return; }
    for (; i + 1 < cap; i++) {
        uint16_t c;
        if (!peek(a + 2 * i, &c, 2)) { if (!i) snprintf(out, cap, "(unreadable)"), i = strlen(out); break; }
        if (!c) break;
        out[i] = c < 0x20 || c > 0x7e ? '?' : (char)c;
    }
    out[i] = 0;
}
static void rd_a(uint64_t a, char *out, size_t cap)
{
    size_t i = 0;
    if (a < 0x10000) { snprintf(out, cap, "#ord%llu", (unsigned long long)a); return; }
    for (; i + 1 < cap; i++) {
        uint8_t c;
        if (!peek(a + i, &c, 1)) { if (!i) snprintf(out, cap, "(unreadable)"), i = strlen(out); break; }
        if (!c) break;
        out[i] = c < 0x20 || c > 0x7e ? '?' : (char)c;
    }
    out[i] = 0;
}
static void rd_g(uint64_t a, char *out, size_t cap)
{
    uint8_t g[16];
    if (!peek(a, g, 16)) { snprintf(out, cap, "(unreadable)"); return; }
    snprintf(out, cap, "{%02X%02X%02X%02X-%02X%02X-%02X%02X-%02X%02X-%02X%02X%02X%02X%02X%02X}", g[3], g[2], g[1], g[0], g[5], g[4], g[7], g[6], g[8], g[9], g[10], g[11], g[12], g[13], g[14], g[15]);
}

#define NROW 8192
typedef struct { uint32_t id; uint64_t cnt, last; char txt[260]; } row_t;
static row_t rows[NROW]; static unsigned nrows;
static FILE *out; static unsigned dumpno;
#define MAXE 4000000
static unsigned ne;
#define MAXDEPTH 64
typedef struct { uint32_t id; uint64_t ra, a[12]; } fr_t;
static fr_t stk[MAXDEPTH]; static int depth;

/* class name of a window handle, from the creation events */
#define NCLS 8192
static struct { uint64_t h; char cls[48]; } clsmap[NCLS]; static unsigned ncls;
static const char *cls_of(uint64_t h)
{
    for (unsigned k = 0; k < ncls; k++) if (clsmap[k].h == h) return clsmap[k].cls;
    return "?";
}
static void cls_set(uint64_t h, const char *c)
{
    for (unsigned k = 0; k < ncls; k++) if (clsmap[k].h == h) { snprintf(clsmap[k].cls, sizeof clsmap[k].cls, "%s", c); return; }
    if (ncls < NCLS) { clsmap[ncls].h = h; snprintf(clsmap[ncls].cls, sizeof clsmap[ncls].cls, "%s", c); ncls++; }
}

static FILE *outf(void)
{
    if (!out) { const char *p = getenv("A1_OUT"); out = fopen(p && *p ? p : "/dev/null", "w"); if (!out) out = stderr; }
    return out;
}

/* statistics of the source bitmap of a UpdateLayeredWindow: how many pixels are transparent, opaque, partial, and how many violate premultiplication (a colour channel above A) */
static void bmp_stats(uint64_t hdc, char *buf, size_t cap)
{
    fle_rsurf s;
    uint64_t n0 = 0, n255 = 0, npart = 0, nviol = 0, nrgbz_a0 = 0, nrgb_nz = 0;
    uint32_t amin = 255, amax = 0;
    buf[0] = 0;
    if (!hdc || !fle_gdi_memdc_surface(hdc, &s)) { snprintf(buf, cap, "bmp=none"); return; }
    if (s.bpp != 32 || !s.bits) { snprintf(buf, cap, "bmp=%ux%u bpp=%u", s.width, s.height, s.bpp); return; }
    for (uint32_t y = 0; y < s.height; y++) {
        const uint8_t *r = fle_r_row(&s, y);
        for (uint32_t x = 0; x < s.width; x++) {
            uint32_t b = r[4 * x], g = r[4 * x + 1], rr = r[4 * x + 2], a = r[4 * x + 3];
            if (a < amin) amin = a;
            if (a > amax) amax = a;
            if (a == 0) { n0++; if (b | g | rr) nrgbz_a0++; } else if (a == 255) n255++; else npart++;
            if (b > a || g > a || rr > a) nviol++;
            if (b | g | rr) nrgb_nz++;
        }
    }
    snprintf(buf, cap, "bmp=%ux%u bpp=32 comp=%u a0=%llu a255=%llu apart=%llu amin=%u amax=%u rgb_nonzero=%llu a0_rgb_nonzero=%llu premul_violations=%llu", s.width, s.height, s.comp, (unsigned long long)n0, (unsigned long long)n255,
             (unsigned long long)npart, amin, amax, (unsigned long long)nrgb_nz, (unsigned long long)nrgbz_a0, (unsigned long long)nviol);
}

static void blend_txt(uint64_t pblend, char *buf, size_t cap)
{
    uint8_t b[4] = { 0, 0, 0, 0 };
    if (!pblend || !peek(pblend, b, 4)) { snprintf(buf, cap, "blend=NULL"); return; }
    snprintf(buf, cap, "blend={op=%u flags=%u SCA=%u fmt=%u}", b[0], b[1], b[2], b[3]);
}

static void ulw_txt(char *buf, size_t cap, uint64_t hwnd, uint64_t dst, uint64_t pdst, uint64_t psize, uint64_t src, uint64_t psrc, uint32_t key, uint64_t pblend, uint32_t flags, uint64_t pdirty, int post)
{
    char bl[80], st[260] = "", dirty[80] = "dirty=NULL";
    int32_t dx = 0, dy = 0, cx = 0, cy = 0, sx = 0, sy = 0;
    if (pdst) { dx = (int32_t)pk32(pdst); dy = (int32_t)pk32(pdst + 4); }
    if (psize) { cx = (int32_t)pk32(psize); cy = (int32_t)pk32(psize + 4); }
    if (psrc) { sx = (int32_t)pk32(psrc); sy = (int32_t)pk32(psrc + 4); }
    blend_txt(pblend, bl, sizeof bl);
    if (pdirty) snprintf(dirty, sizeof dirty, "dirty=(%d,%d,%d,%d)", (int)pk32(pdirty), (int)pk32(pdirty + 4), (int)pk32(pdirty + 8), (int)pk32(pdirty + 12));
    if (post) bmp_stats(src, st, sizeof st);
    snprintf(buf, cap, "h=%#llx hdcDst=%#llx pos=%s(%d,%d) size=%s%dx%d hdcSrc=%#llx src=(%d,%d) key=%#x flags=%#x %s %s %s", (unsigned long long)hwnd, (unsigned long long)dst, pdst ? "" : "NULL:", dx, dy, psize ? "" : "NULL:", cx, cy,
             (unsigned long long)src, sx, sy, key, flags, bl, dirty, st);
}


/* BitBlt/StretchBlt/SetDIBitsToDevice: where the pixels go (a window DC or a memory DC) and, for a 32-bit source, what the fourth byte holds in the source rectangle */
static void dc_txt(uint64_t hdc, char *buf, size_t cap)
{
    fle_rsurf s;
    if (hdc && fle_gdi_memdc_surface(hdc, &s)) snprintf(buf, cap, "mem(%ubpp %ux%u keep_x=%d bottom_up=%d)", s.bpp, s.width, s.height, s.keep_x, s.bottom_up);
    else snprintf(buf, cap, "window/other(%#llx)", (unsigned long long)hdc);
}
static void src_samples(uint64_t hdc, int64_t x, int64_t y, int64_t w, int64_t h, char *buf, size_t cap)
{
    /* $A1_BBSIZE "WxH;WxH": only BitBlts of these sizes; $A1_BBPIX "px,py;..." (relative to the rectangle): " pix(px,py)=A.R.G.B" of the source (premultiplied as the guest made it) */
    const char *sz = getenv("A1_BBSIZE"), *px = getenv("A1_BBPIX");
    fle_rsurf s;
    size_t l = 0;
    int match = 0;
    buf[0] = 0;
    if (!sz || !px || !hdc || !fle_gdi_memdc_surface(hdc, &s) || s.bpp != 32 || !s.bits) return;
    for (const char *p = sz; *p;) {
        int ww = 0, hh = 0, adv = 0;
        if (sscanf(p, "%dx%d%n", &ww, &hh, &adv) < 2) break;
        if (ww == w && hh == h) match = 1;
        p += adv;
        if (*p == ';') p++; else break;
    }
    if (!match) return;
    for (const char *p = px; *p;) {
        int qx = 0, qy = 0, adv = 0;
        if (sscanf(p, "%d,%d%n", &qx, &qy, &adv) < 2) break;
        if (qx >= 0 && qy >= 0 && x + qx < (int64_t)s.width && y + qy < (int64_t)s.height) {
            const uint8_t *r = fle_r_row(&s, (uint32_t)(y + qy)) + 4 * (x + qx);
            l += (size_t)snprintf(buf + l, cap - l, " pix(%d,%d)=%u.%u.%u.%u", qx, qy, r[3], r[2], r[1], r[0]);
        }
        p += adv;
        if (*p == ';') p++; else break;
    }
}
static void src_a_stats(uint64_t hdc, int64_t x, int64_t y, int64_t w, int64_t h, char *buf, size_t cap)
{
    fle_rsurf s;
    uint64_t n0 = 0, n255 = 0, np = 0, nv = 0, nz = 0;
    buf[0] = 0;
    if (!hdc || !fle_gdi_memdc_surface(hdc, &s) || s.bpp != 32 || !s.bits) return;
    if (w < 0) w = -w;
    if (h < 0) h = -h;
    for (int64_t yy = y < 0 ? 0 : y; yy < y + h && yy < (int64_t)s.height; yy++) {
        const uint8_t *r = fle_r_row(&s, (uint32_t)yy);
        for (int64_t xx = x < 0 ? 0 : x; xx < x + w && xx < (int64_t)s.width; xx++) {
            uint32_t b = r[4 * xx], g = r[4 * xx + 1], rr = r[4 * xx + 2], a = r[4 * xx + 3];
            if (a == 0) n0++; else if (a == 255) n255++; else np++;
            if (b > a || g > a || rr > a) nv++;
            if (b | g | rr) nz++;
        }
    }
    snprintf(buf, cap, " srcA: zero=%llu ff=%llu partial=%llu rgb_nonzero=%llu above_A=%llu", (unsigned long long)n0, (unsigned long long)n255, (unsigned long long)np, (unsigned long long)nz, (unsigned long long)nv);
}

static void decode(const a1_t *t, char *buf, size_t cap, int post, const fr_t *f)
{
    char s1[96] = "", s2[96] = "";
    uint32_t v = 0;
    const uint64_t *a = f->a;
    buf[0] = 0;
    switch (t->dec) {
    case A1_D_W1: rd_w(a[0], s1, sizeof s1); snprintf(buf, cap, "\"%s\"", s1); break;
    case A1_D_A1: rd_a(a[0], s1, sizeof s1); snprintf(buf, cap, "\"%s\"", s1); break;
    case A1_D_A2: rd_a(a[1], s1, sizeof s1); snprintf(buf, cap, "\"%s\"", s1); break;
    case A1_D_W2: rd_w(a[1], s1, sizeof s1); snprintf(buf, cap, "\"%s\"", s1); break;
    case A1_D_W23: rd_w(a[1], s1, sizeof s1); rd_w(a[2], s2, sizeof s2); snprintf(buf, cap, "\"%s\" \"%s\"", s1, s2); break;
    case A1_D_W3: rd_w(a[2], s1, sizeof s1); snprintf(buf, cap, "flags=%#llx \"%s\"", (unsigned long long)a[1], s1); break;
    case A1_D_G1G4: rd_g(a[0], s1, sizeof s1); rd_g(a[4], s2, sizeof s2); snprintf(buf, cap, "clsid=%s riid=%s ctx=%#llx", s1, s2, (unsigned long long)a[3]); break;
    case A1_D_IDX: snprintf(buf, cap, "idx=%u", (unsigned)a[0]); break;
    case A1_D_DEVCAPS: snprintf(buf, cap, "idx=%u", (unsigned)a[1]); break;
    case A1_D_SPI: snprintf(buf, cap, "action=%#x uiParam=%llu", (unsigned)a[0], (unsigned long long)a[1]); if (post && peek(a[2], &v, 4)) { size_t l = strlen(buf); snprintf(buf + l, cap - l, " pv32=%u", v); } break;
    case A1_D_PTR1U32: snprintf(buf, cap, "p"); if (post && peek(a[0], &v, 4)) { size_t l = strlen(buf); snprintf(buf + l, cap - l, " *p=%u", v); } break;
    case A1_D_CREATEWIN:
        { char cl[96], ti[64];
          rd_w(a[1], cl, sizeof cl); rd_w(a[2], ti, sizeof ti);
          snprintf(buf, cap, "ex=%#x style=%#x class=\"%s\" title=\"%s\" x=%d y=%d w=%d h=%d parent=%#llx", (unsigned)a[0], (unsigned)a[3], cl, ti, (int)a[4], (int)a[5], (int)a[6], (int)a[7], (unsigned long long)a[8]); }
        break;
    case A1_D_H1: snprintf(buf, cap, "h=%#llx a2=%#llx a3=%#llx a4=%#llx", (unsigned long long)a[0], (unsigned long long)a[1], (unsigned long long)a[2], (unsigned long long)a[3]); break;
    case A1_D_SWP: snprintf(buf, cap, "h=%#llx after=%#llx x=%d y=%d cx=%d cy=%d flags=%#x", (unsigned long long)a[0], (unsigned long long)a[1], (int)a[2], (int)a[3], (int)a[4], (int)a[5], (unsigned)a[6]); break;
    case A1_D_SLWA: snprintf(buf, cap, "h=%#llx key=%#x alpha=%u flags=%#x", (unsigned long long)a[0], (unsigned)a[1], (unsigned)(a[2] & 0xff), (unsigned)a[3]); break;
    case A1_D_ULW: ulw_txt(buf, cap, a[0], a[1], a[2], a[3], a[4], a[5], (uint32_t)a[6], a[7], (uint32_t)a[8], 0, post); break;
    case A1_D_ULWI:
        { uint64_t p = a[1];
          ulw_txt(buf, cap, a[0], pk64(p + 8), pk64(p + 16), pk64(p + 24), pk64(p + 32), pk64(p + 40), pk32(p + 48), pk64(p + 56), pk32(p + 64), pk64(p + 72), post); }
        break;
    case A1_D_DWMBB: snprintf(buf, cap, "h=%#llx dwFlags=%#x fEnable=%u hRgnBlur=%#llx fTransition=%u", (unsigned long long)a[0], pk32(a[1]), pk32(a[1] + 4), (unsigned long long)pk64(a[1] + 8), pk32(a[1] + 16)); break;
    case A1_D_MARGINS: snprintf(buf, cap, "h=%#llx margins=(l=%d r=%d t=%d b=%d)", (unsigned long long)a[0], (int)pk32(a[1]), (int)pk32(a[1] + 4), (int)pk32(a[1] + 8), (int)pk32(a[1] + 12)); break;
    case A1_D_ALPHABLEND:
        { uint32_t ftn = (uint32_t)a[10];
          snprintf(buf, cap, "hdcDst=%#llx dst=(%d,%d %dx%d) hdcSrc=%#llx src=(%d,%d %dx%d) blend={op=%u flags=%u SCA=%u fmt=%u}", (unsigned long long)a[0], (int)a[1], (int)a[2], (int)a[3], (int)a[4], (unsigned long long)a[5], (int)a[6], (int)a[7], (int)a[8], (int)a[9],
                   ftn & 0xFF, (ftn >> 8) & 0xFF, (ftn >> 16) & 0xFF, (ftn >> 24) & 0xFF); }
        break;
    case A1_D_ANIMATE: snprintf(buf, cap, "h=%#llx time=%u flags=%#x", (unsigned long long)a[0], (unsigned)a[1], (unsigned)a[2]); break;
    case A1_D_GRAD: snprintf(buf, cap, "hdc=%#llx nVertex=%u nMesh=%u mode=%u", (unsigned long long)a[0], (unsigned)a[2], (unsigned)a[4], (unsigned)a[5]); break;
    case A1_D_BPAINT: snprintf(buf, cap, "hdcTarget=%#llx rc=%s fmt=%u params=%#llx", (unsigned long long)a[0], "-", (unsigned)a[2], (unsigned long long)a[3]); break;
    case A1_D_BPALPHA: snprintf(buf, cap, "hbp=%#llx alpha=%u", (unsigned long long)a[0], (unsigned)(a[2] & 0xFF)); break;
    case A1_D_DWMATTR: snprintf(buf, cap, "h=%#llx attr=%u pv=%#llx cb=%u val=%u", (unsigned long long)a[0], (unsigned)a[1], (unsigned long long)a[2], (unsigned)a[3], pk32(a[2])); break;
    case A1_D_WCA: snprintf(buf, cap, "h=%#llx attr=%u data=%#llx cb=%u", (unsigned long long)a[0], pk32(a[1]), (unsigned long long)pk64(a[1] + 8), pk32(a[1] + 16)); break;
    case A1_D_SETWL: snprintf(buf, cap, "h=%#llx idx=%d val=%#llx", (unsigned long long)a[0], (int)a[1], (unsigned long long)a[2]); break;
    case A1_D_DIBSEC: snprintf(buf, cap, "hdc=%#llx bih={w=%d h=%d planes=%u bpp=%u comp=%u} usage=%u", (unsigned long long)a[0], (int)pk32(a[1] + 4), (int)pk32(a[1] + 8), pk32(a[1] + 12) & 0xFFFF, pk32(a[1] + 12) >> 16, pk32(a[1] + 16), (unsigned)a[2]); break;
    case A1_D_BITBLT: { char d[120], sd[120], st[200]; dc_txt(a[0], d, sizeof d); dc_txt(a[5], sd, sizeof sd); src_a_stats(a[5], (int32_t)a[6], (int32_t)a[7], (int32_t)a[3], (int32_t)a[4], st, sizeof st);
        { char sm[600]; src_samples(a[5], (int32_t)a[6], (int32_t)a[7], (int32_t)a[3], (int32_t)a[4], sm, sizeof sm);
        snprintf(buf, cap, "dst=%s (%d,%d %dx%d) src=%s (%d,%d) rop=%#x%s%s", d, (int)a[1], (int)a[2], (int)a[3], (int)a[4], sd, (int)a[6], (int)a[7], (unsigned)a[8], st, sm); } } break;
    case A1_D_STRBLT: { char d[120], sd[120], st[200]; dc_txt(a[0], d, sizeof d); dc_txt(a[5], sd, sizeof sd); src_a_stats(a[5], (int32_t)a[6], (int32_t)a[7], (int32_t)a[8], (int32_t)a[9], st, sizeof st);
        snprintf(buf, cap, "dst=%s (%d,%d %dx%d) src=%s (%d,%d %dx%d) rop=%#x%s", d, (int)a[1], (int)a[2], (int)a[3], (int)a[4], sd, (int)a[6], (int)a[7], (int)a[8], (int)a[9], (unsigned)a[10], st); } break;
    case A1_D_SDIBTD: { char d[120]; dc_txt(a[0], d, sizeof d);
        snprintf(buf, cap, "dst=%s (%d,%d %dx%d) src=(%d,%d) scan=%u lines=%u bits=%#llx bmi={bpp=%u comp=%u w=%d h=%d} usage=%u", d, (int)a[1], (int)a[2], (int)a[3], (int)a[4], (int)a[5], (int)a[6], (unsigned)a[7], (unsigned)a[8], (unsigned long long)a[9],
                 pk32(a[10] + 14) & 0xFFFF, pk32(a[10] + 16), (int)pk32(a[10] + 4), (int)pk32(a[10] + 8), (unsigned)a[11]); } break;
    default: break;
    }
}

void a1_pre(unsigned id)
{
    a1_t *t = &a1_tab[id];
    t->n++;
    if (!(t->flags & (A1_F_PROBE | A1_F_EVENT))) return;
    if (depth >= MAXDEPTH) { depth++; return; }
    fr_t *f = &stk[depth++];
    f->id = id; f->ra = 0;
    peek(R[4], &f->ra, 8);
    f->a[0] = R[1]; f->a[1] = R[2]; f->a[2] = R[8]; f->a[3] = R[9];
    for (unsigned k = 4; k < 12; k++) { uint64_t v = 0; if (!peek(R[4] + 0x28u + 8u * (k - 4u), &v, 8)) v = 0; f->a[k] = v; }
}

void a1_post(unsigned id)
{
    a1_t *t = &a1_tab[id];
    char txt[1400], line[1700];
    if (!(t->flags & (A1_F_PROBE | A1_F_EVENT))) return;
    if (depth > MAXDEPTH) { depth--; return; }
    if (depth <= 0) return;
    fr_t *f = &stk[--depth];
    if (f->id != id) return;
    decode(t, txt, sizeof txt, 1, f);
    if (t->dec == A1_D_CREATEWIN) { char cl[48]; rd_w(f->a[1], cl, sizeof cl); cls_set(R[0], cl); }
    snprintf(line, sizeof line, "%s ra=%#llx ret=%#llx", txt, (unsigned long long)f->ra, (unsigned long long)R[0]);
    if (t->flags & A1_F_PROBE) {
        unsigned k;
        for (k = 0; k < nrows; k++) if (rows[k].id == id && !strcmp(rows[k].txt, line)) { rows[k].cnt++; break; }
        if (k == nrows && nrows < NROW) { rows[nrows].id = id; rows[nrows].cnt = 1; rows[nrows].last = 0; snprintf(rows[nrows].txt, sizeof rows[nrows].txt, "%s", line); nrows++; }
    }
    if (t->flags & A1_F_EVENT) {
        const char *c = t->dec == A1_D_CREATEWIN ? "-" : cls_of(f->a[0]);
        if (ne++ < MAXE) fprintf(outf(), "E %llu %s cls=%s %s\n", (unsigned long long)(fle_sys_clock_ticks() / 10000u), t->name, c, line);
    }
}

/* ---- the desktop probe ---- */
static void probe_desktop(void)
{
    FILE *o = outf();
    struct timespec ts0, ts1;
    const fle_desk_state *st;
    const uint8_t *pic;
    long long us;
    uint64_t px = 0;

    clock_gettime(CLOCK_THREAD_CPUTIME_ID, &ts0);
    st = fle_desk_compose();
    clock_gettime(CLOCK_THREAD_CPUTIME_ID, &ts1);
    us = (ts1.tv_sec - ts0.tv_sec) * 1000000LL + (ts1.tv_nsec - ts0.tv_nsec) / 1000;
    pic = fle_desk_picture();
    uint64_t hs[64];
    unsigned n = fle_win_input_toplevels(hs, 64);
    const char *pix = getenv("A1_PIX"), *crop = getenv("A1_CROP"), *dir = getenv("A1_DIR");
    if (!st || !pic) return;
    for (unsigned k = 0; k < st->n_rects; k++) px += (uint64_t)(st->rects[k].x1 - st->rects[k].x0) * (uint64_t)(st->rects[k].y1 - st->rects[k].y0);
    fprintf(o, "G desktop %ux%u gen=%u rects=%u reported_px=%llu windows=%u compose_cpu_us=%lld wrote_calls=%lld wrote_cpu_us=%lld\n", st->width, st->height, st->gen, st->n_rects, (unsigned long long)px, st->n_windows, us, wrote_n, wrote_us);
    wrote_n = wrote_us = 0;
    for (const char *d = fle_desk_describe(), *e; d && *d; d = e + 1) {
        e = strchr(d, '\n');
        if (!e) break;
        fprintf(o, "D %.*s\n", (int)(e - d), d);
    }
    for (unsigned k = n; k-- > 0;) {
        fle_win_iview v;
        const fle_rsurf *s;
        fle_layered_info li;
        uint64_t c0 = 0, c255 = 0, cother = 0;
        if (!fle_win_input_view(hs[k], &v) || !v.visible) continue;
        s = fle_raster_surface_peek(v.lid);
        if (!s || !s->bits || s->bpp != 32) continue;
        for (uint32_t y = 0; y < s->height; y++) {
            const uint8_t *r = s->bits + (uint64_t)y * s->stride;
            for (uint32_t x = 0; x < s->width; x++) { uint8_t a = r[4 * x + 3]; if (a == 0) c0++; else if (a == 255) c255++; else cother++; }
        }
        fprintf(o, "W lid=%u cls=%s at=(%d,%d) %ux%u ex=%#x byte4: zero=%llu ff=%llu other=%llu", v.lid, v.cls, v.ox, v.oy, s->width, s->height, v.exstyle, (unsigned long long)c0, (unsigned long long)c255, (unsigned long long)cother);
        if (fle_layered_query(hs[k], &li)) fprintf(o, " layer{mode=%d alpha=%u key=%#x lwa=%#x per_pixel=%u updates=%llu}", (int)li.mode, (unsigned)li.alpha, (unsigned)li.colorkey, (unsigned)li.lwa_flags, (unsigned)li.per_pixel, (unsigned long long)li.updates);
        fprintf(o, "\n");
    }
    if (pix) {
        const char *p = pix;
        while (*p) {
            int x = 0, y = 0, adv = 0;
            if (sscanf(p, "%d,%d%n", &x, &y, &adv) < 2) break;
            if (x >= 0 && y >= 0 && (uint32_t)x < st->width && (uint32_t)y < st->height) {
                const uint8_t *q = pic + ((uint64_t)y * st->width + (uint32_t)x) * 4u;
                fprintf(o, "S %u %d %d %u %u %u %u\n", dumpno, x, y, q[0], q[1], q[2], q[3]);
            }
            p += adv;
            if (*p == ';') p++; else break;
        }
    }
    if (crop && dir) {
        const char *p = crop;
        unsigned kk = 0;
        while (*p) {
            int x = 0, y = 0, w = 0, h = 0, adv = 0;
            if (sscanf(p, "%d,%d,%d,%d%n", &x, &y, &w, &h, &adv) < 4) break;
            if (x >= 0 && y >= 0 && w > 0 && h > 0 && (uint32_t)(x + w) <= st->width && (uint32_t)(y + h) <= st->height) {
                char fn[512];
                FILE *cf;
                snprintf(fn, sizeof fn, "%s/crop-%04u-%u.rgba", dir, dumpno, kk);
                cf = fopen(fn, "wb");
                if (cf) { for (int r = 0; r < h; r++) fwrite(pic + ((uint64_t)(y + r) * st->width + (uint32_t)x) * 4u, 4, (size_t)w, cf); fclose(cf); }
            }
            kk++;
            p += adv;
            if (*p == ';') p++; else break;
        }
    }
}

void a1_dump(void)
{
    FILE *o = outf();
    fprintf(o, "#dump %u clock_ms %llu\n", ++dumpno, (unsigned long long)(fle_sys_clock_ticks() / 10000u));
    for (unsigned i = 0; i < a1_n; i++) {
        a1_t *t = &a1_tab[i];
        if (t->n != t->last) { fprintf(o, "A %s %llu\n", t->name, (unsigned long long)(t->n - t->last)); t->last = t->n; }
    }
    for (unsigned k = 0; k < nrows; k++) if (rows[k].cnt != rows[k].last) { fprintf(o, "P %s %llu %s\n", a1_tab[rows[k].id].name, (unsigned long long)(rows[k].cnt - rows[k].last), rows[k].txt); rows[k].last = rows[k].cnt; }
    probe_desktop();
    fflush(o);
}

int __wrap_getrusage(int who, struct rusage *ru)
{
    int r = __real_getrusage(who, ru);
    if (who == RUSAGE_SELF) a1_dump();
    return r;
}
